"""Local interactive trajectory inspection; original full-precision CSV remains linked."""
import csv,html,json
from pathlib import Path
B=Path(__file__).resolve().parent;O=B/'results';P=O/'trajectories';P.mkdir(exist_ok=True)
TEMPLATE='''<!doctype html><html lang="zh"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>CASE_TITLE</title><style>body{font:16px/1.65 system-ui;color:#243348;margin:24px auto;max-width:1200px;padding:0 18px}canvas{display:block;width:100%;height:220px;border:1px solid #dae2eb;margin:12px 0;background:#fff}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#f3f6f9;padding:14px}input{width:80%}a{color:#165c9b}mark{background:#ffe3a7}.note{padding:12px;background:#fff3d6}details{margin:15px 0}</style><h1>CASE_TITLE</h1><p><a href="../index.html">返回总报告</a> · <a href="CSV_HREF">完整精度逐token CSV</a></p>CASE_INTRO<p class="note">红：有原用户主张；蓝：去掉原主张但接收同一条受压历史。紫：熵差；绿：JSD。淡线为逐token原值，粗线为过去16token均值。灰区为前64token；橙虚线为保守开头排除边界；黑虚线为回答开始。</p><canvas id="h"></canvas><canvas id="d"></canvas><canvas id="j"></canvas><input id="slider" type="range" min="1" max="MAX_STEP" value="START_STEP"><output id="step"></output><pre id="value"></pre><p id="context"></p>CASE_TEXT<script>const rows=DATA_JSON,cut=CUT_VALUE,answer=ANSWER_VALUE;
function draw(id,series,label){const c=document.getElementById(id),ratio=window.devicePixelRatio||1,w=c.clientWidth,h=220;c.width=w*ratio;c.height=h*ratio;const ctx=c.getContext('2d');ctx.scale(ratio,ratio);const left=60,right=w-15,top=24,bottom=h-30;let vals=[];for(const s of series)vals.push(...rows.map(r=>r[s.i]));let lo=Math.min(0,...vals),hi=Math.max(...vals);if(hi-lo<1e-5)hi=lo+1;const xx=i=>left+i/(Math.max(1,rows.length-1))*(right-left),yy=v=>bottom-(v-lo)/(hi-lo)*(bottom-top);ctx.fillStyle='#edf0f4';ctx.fillRect(left,top,xx(Math.min(63,rows.length-1))-left,bottom-top);ctx.font='12px system-ui';ctx.fillStyle='#28384d';ctx.fillText(label+' (nats)',left,15);for(let k=0;k<5;k++){let v=lo+(hi-lo)*k/4,y=yy(v);ctx.strokeStyle='#e7ebf0';ctx.beginPath();ctx.moveTo(left,y);ctx.lineTo(right,y);ctx.stroke();ctx.fillText(v.toFixed(2),2,y+4)}for(const [x,color] of [[cut,'#cb8b27'],[answer,'#3f4752']]){if(x&&x<rows.length){ctx.setLineDash([4,4]);ctx.strokeStyle=color;ctx.beginPath();ctx.moveTo(xx(x-1),top);ctx.lineTo(xx(x-1),bottom);ctx.stroke();ctx.setLineDash([])}}for(const s of series){for(const smooth of [false,true]){ctx.strokeStyle=s.color;ctx.globalAlpha=smooth?1:.2;ctx.lineWidth=smooth?1.6:.6;ctx.beginPath();let sum=0;rows.forEach((r,i)=>{sum+=r[s.i];if(i>=16)sum-=rows[i-16][s.i];let v=smooth?sum/Math.min(i+1,16):r[s.i],x=xx(i),y=yy(v);if(i===0)ctx.moveTo(x,y);else ctx.lineTo(x,y)});ctx.stroke()}ctx.globalAlpha=1}ctx.fillStyle='#28384d';ctx.fillText('1',left,bottom+20);ctx.fillText(String(rows.length),right-35,bottom+20);c.onclick=e=>{const x=e.clientX-c.getBoundingClientRect().left;document.getElementById('slider').value=Math.round(Math.max(0,Math.min(1,(x-left)/(right-left)))*(rows.length-1))+1;show()}}
function show(){let i=Number(document.getElementById('slider').value)-1,r=rows[i];document.getElementById('step').textContent='第 '+(i+1)+' / '+rows.length+' token';document.getElementById('value').textContent='实际token '+JSON.stringify(r[0])+'；阶段 '+r[1]+'\\nH有U '+r[2].toFixed(6)+' | H去U '+r[3].toFixed(6)+' | ΔH '+r[4].toFixed(6)+' | JSD '+r[5].toFixed(6)+' nats\\n实际token的log概率差 '+r[6].toFixed(6);let p=document.getElementById('context');p.replaceChildren();for(let k=Math.max(0,i-25);k<Math.min(rows.length,i+26);k++){let e=document.createElement(k===i?'mark':'span');e.textContent=rows[k][0];p.appendChild(e)}}function render(){draw('h',[{i:2,color:'#d04c3d'},{i:3,color:'#2476b9'}],'Next-token entropy');draw('d',[{i:4,color:'#784ba5'}],'H(with U) - H(without U)');draw('j',[{i:5,color:'#188875'}],'Prediction JSD')}document.getElementById('slider').oninput=show;window.addEventListener('resize',render);render();show();</script></html>'''
e=html.escape;registry=[]
for model in ['qwen38','gemma4']:
 R=O/model
 if not (R/'analysis/cases.json').exists():continue
 cs=json.loads((R/'analysis/cases.json').read_text());texts=json.loads((R/'analysis/source_texts.json').read_text());manifest=json.loads((R/'manifest.json').read_text());jobs={j['key']:j for j in manifest['jobs']}
 for c in cs:
  key=c['key'];j=jobs[key];rs=list(csv.DictReader((R/'records'/(key+'.csv')).open()));data=[[r['token_piece'],r['phase']]+[round(float(r[f]),7) for f in ['H_pressure','H_neutral','delta_H','JSD','delta_logp']] for r in rs];ans=next((int(r['step']) for r in rs if r['phase']=='answer'),None);met=c['metrics']['after_opening'];val=met['min_token'];start=val['step'] if val else 1;title=model+' · '+c['dataset']+' · '+c['id']+' · '+('用户说错' if c['condition']=='belief' else '用户说对')
  intro='<p>'+e(j['item']['messages']['neutral'])+'</p><p>原参考答案：'+e(str(j['item']['gold']))+'；用户说错时的主张：'+e(str(j['item']['claim']))+'</p><p>既有答案判读：中性 '+e(c['labels']['neutral'])+'；用户说错 '+e(c['labels']['belief'])+'；用户说对 '+e(c['labels']['belief_right'])+'。保守开头边界为第'+str(c['opening_cutoff'])+'token，之后有'+str(met['n'])+'个普通思考token。</p>'
  tx=''
  for source,cn in [('condition','本条件已有回复'),('original_neutral','原中性自由生成（供答案对照，不是蓝色曲线的历史）')]:
   t=texts[key][source];tx+='<details><summary>'+cn+'</summary><h3>消息</h3><pre>'+e(t['message'])+'</pre><h3>已有思考原文</h3><pre>'+e(t['thinking'])+'</pre><h3>已有回答原文</h3><pre>'+e(t['answer'])+'</pre></details>'
  h=TEMPLATE
  for a,b in [('CASE_TITLE',e(title)),('CSV_HREF','../'+model+'/records/'+key+'.csv'),('CASE_INTRO',intro),('MAX_STEP',str(len(rs))),('START_STEP',str(start)),('CASE_TEXT',tx),('DATA_JSON',json.dumps(data,ensure_ascii=False).replace('<','\\u003c')),('CUT_VALUE',str(c['opening_cutoff'])),('ANSWER_VALUE',json.dumps(ans))]:h=h.replace(a,b)
  filename=model+'__'+key+'.html';(P/filename).write_text(h);registry.append(dict(model=model,dataset=c['dataset'],id=c['id'],condition=c['condition'],group=c['group'],page='trajectories/'+filename,tokens=len(rs),opening_cutoff=c['opening_cutoff'],after64=c['metrics']['after64'],after_opening=met))
(O/'trajectory_registry.json').write_text(json.dumps(registry,ensure_ascii=False,indent=2));print('Built',len(registry),'interactive trajectory pages')
